import Box from '@mui/material/Box';
import { useDefaultProps } from '@mui/material/DefaultPropsProvider';
import ListItemIcon from '@mui/material/ListItemIcon';
import ListItemText from '@mui/material/ListItemText';
import ListSubheader from '@mui/material/ListSubheader';
import Menu, { type MenuProps } from '@mui/material/Menu';
import MenuItem, { type MenuItemProps } from '@mui/material/MenuItem';
import { mergeSlotProps } from '@mui/material/utils';
import clsx from 'clsx';
import { mergeSx } from 'merge-sx';
import {
  Children,
  cloneElement,
  forwardRef,
  Fragment,
  isValidElement,
  type MouseEvent,
  type ReactNode,
} from 'react';
import {
  menuGroupStyles,
  menuHeaderStyles,
  menuItemStyles,
  menuListStyles,
  menuPaperStyles,
  menuRootStyles,
} from './sv-menu.styles.ts';

export interface SvMenuItem {
  id: string;
  label: ReactNode;
  description?: ReactNode;
  icon?: ReactNode;
  disabled?: boolean;
  onClick?: (event: MouseEvent<HTMLLIElement>) => void;
  slotProps?: { item?: Omit<MenuItemProps, 'onClick' | 'disabled'> };
}
export type SvMenuCloseReason = Parameters<
  NonNullable<MenuProps['onClose']>
>[1];
export type SvMenuProps = Omit<MenuProps, 'children'> & {
  header?: ReactNode;
  footer?: ReactNode;
} & (
    | { children?: ReactNode; items?: never }
    | { children?: never; items: readonly SvMenuItem[] }
  );

declare module '@mui/material/styles' {
  interface ComponentsPropsList {
    SvMenu: SvMenuProps;
  }
  interface Components {
    SvMenu?: { defaultProps?: Partial<SvMenuProps> | undefined } | undefined;
  }
}

// Clone only native presentation elements; custom components keep their own contract.
function styleItems(children: ReactNode, defaults: MenuItemProps): ReactNode {
  return Children.map(children, (child) => {
    if (!isValidElement<MenuItemProps>(child)) return child;
    if (child.type === Fragment) {
      return cloneElement(child, {
        children: styleItems(child.props.children, defaults),
      });
    }
    if (child.type !== MenuItem) return child;
    return cloneElement(child, {
      className: clsx('SvMenu-item', defaults.className, child.props.className),
      sx: mergeSx(menuItemStyles, defaults.sx, child.props.sx),
    });
  });
}

export const SvMenu = forwardRef<HTMLDivElement, SvMenuProps>(
  function SvMenu(inProps, ref) {
    const muiDefaults = useDefaultProps<Partial<SvMenuProps>>({
      props: {},
      name: 'MuiMenu',
    });
    const svDefaults = useDefaultProps<Partial<SvMenuProps>>({
      props: {},
      name: 'SvMenu',
    });
    const svProps = useDefaultProps({ props: inProps, name: 'SvMenu' });
    const resolved = useDefaultProps({ props: svProps, name: 'MuiMenu' });
    const {
      items: _items,
      children: _children,
      header,
      footer,
      className,
      sx: _sx,
      slotProps,
      ...props
    } = resolved;
    const itemDefaults = useDefaultProps<MenuItemProps>({
      props: {},
      name: 'MuiMenuItem',
    });
    // Content is one choice even when theme defaults use the other representation.
    const contentProps = [inProps, svDefaults, muiDefaults].find(
      (value) => value.children !== undefined || value.items !== undefined
    );
    const content =
      contentProps?.items !== undefined
        ? contentProps.items.map((item) => (
            <MenuItem
              {...item.slotProps?.item}
              key={item.id}
              disabled={item.disabled}
              onClick={item.onClick}
            >
              {item.icon != null && <ListItemIcon>{item.icon}</ListItemIcon>}
              {item.description != null ? (
                <ListItemText
                  primary={item.label}
                  secondary={item.description}
                  slotProps={{
                    primary: { component: 'div' },
                    secondary: { component: 'div' },
                  }}
                />
              ) : (
                item.label
              )}
            </MenuItem>
          ))
        : contentProps?.children;
    const framed = header != null || footer != null;
    const body = styleItems(content, itemDefaults);
    return (
      <Menu
        {...props}
        ref={ref}
        className={clsx('SvMenu-root', className)}
        sx={mergeSx(menuRootStyles, muiDefaults.sx, svDefaults.sx, inProps.sx)}
        slotProps={{
          ...slotProps,
          paper: mergeSlotProps(slotProps?.paper, {
            className: 'SvMenu-paper',
            sx: mergeSx(
              menuPaperStyles,
              framed && {
                display: 'flex',
                flexDirection: 'column',
                overflow: 'hidden',
              }
            ),
          }),
          list: mergeSlotProps(slotProps?.list, {
            className: 'SvMenu-list',
            sx: mergeSx(
              menuListStyles,
              framed && {
                display: 'flex',
                flexDirection: 'column',
                minHeight: 0,
                overflow: 'hidden',
              }
            ),
          }),
        }}
      >
        {header != null && (
          <ListSubheader
            role="presentation"
            disableSticky
            className="SvMenu-header"
            sx={menuHeaderStyles}
          >
            {header}
          </ListSubheader>
        )}
        {framed ? (
          <Box
            component="li"
            role="none"
            className="SvMenu-body"
            sx={{
              minHeight: 0,
              overflowY: 'auto',
              overflowX: 'hidden',
              flex: '1 1 auto',
            }}
          >
            <Box component="ul" role="group" sx={menuGroupStyles}>
              {body}
            </Box>
          </Box>
        ) : (
          body
        )}
        {footer != null && (
          <Box
            component="li"
            role="none"
            className="SvMenu-footer"
            sx={{
              flexShrink: 0,
              borderTop: '0.5px solid var(--SvMenu-stroke)',
            }}
          >
            <Box component="ul" role="group" sx={menuGroupStyles}>
              {styleItems(footer, itemDefaults)}
            </Box>
          </Box>
        )}
      </Menu>
    );
  }
);
